mapper.select:
SELECT g.id, g.seller_id AS sellerId, g.goods_name AS goodsName, g.price, g.small_pic AS smallPic, g.audit_status AS auditStatus, g.is_marketable AS isMarketable, g.category1_id AS category1Id, g.category2_id AS category2Id, g.category3_id AS category3Id, c1.name AS category1Name, c2.name AS category2Name, c3.name AS category3Name FROM tb_goods g LEFT JOIN tb_item_cat c1 ON g.category1_id = c1.id LEFT JOIN tb_item_cat c2 ON g.category2_id = c2.id LEFT JOIN tb_item_cat c3 ON g.category3_id = c3.id
g.is_delete = '0'
AND g.seller_id = #{sellerId}
AND g.goods_name LIKE CONCAT('%', #{goodsName}, '%')
AND g.audit_status = #{auditStatus}
ORDER BY g.id DESC

